-- ============================================================
-- Sistem Pengaduan Masyarakat (e-Lapor) - PHP Native + MySQL
-- Import lewat phpMyAdmin atau:  mysql -u root -p < database/pengaduan_masyarakat.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS pengaduan_masyarakat CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pengaduan_masyarakat;

DROP TABLE IF EXISTS tanggapan;
DROP TABLE IF EXISTS aduan;
DROP TABLE IF EXISTS kategori;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS unit;
DROP TABLE IF EXISTS pengaturan;

CREATE TABLE pengaturan (
  id INT PRIMARY KEY,
  nama_instansi VARCHAR(150) NOT NULL,
  nama_layanan VARCHAR(60) NOT NULL,
  alamat VARCHAR(255),
  telepon VARCHAR(30)
) ENGINE=InnoDB;

CREATE TABLE unit (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  role ENUM('admin','petugas') NOT NULL DEFAULT 'petugas',
  unit_id INT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (unit_id) REFERENCES unit(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE kategori (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(80) NOT NULL,
  unit_id INT NULL,            -- unit penanggung jawab default
  sla_hari TINYINT NOT NULL DEFAULT 7,
  FOREIGN KEY (unit_id) REFERENCES unit(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE aduan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode VARCHAR(20) NOT NULL UNIQUE,
  nama VARCHAR(100),
  telepon VARCHAR(20),
  anonim TINYINT(1) NOT NULL DEFAULT 0,
  kategori_id INT,
  unit_id INT,
  judul VARCHAR(150) NOT NULL,
  isi TEXT NOT NULL,
  lokasi VARCHAR(200),
  foto VARCHAR(100),
  prioritas ENUM('rendah','sedang','tinggi') NOT NULL DEFAULT 'sedang',
  status ENUM('baru','diverifikasi','diproses','selesai','ditolak') NOT NULL DEFAULT 'baru',
  rating TINYINT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  selesai_at DATETIME NULL,
  INDEX (status), INDEX (created_at),
  FOREIGN KEY (kategori_id) REFERENCES kategori(id) ON DELETE SET NULL,
  FOREIGN KEY (unit_id) REFERENCES unit(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE tanggapan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  aduan_id INT NOT NULL,
  user_id INT NULL,
  status ENUM('baru','diverifikasi','diproses','selesai','ditolak') NOT NULL,
  isi TEXT NOT NULL,
  internal TINYINT(1) NOT NULL DEFAULT 0,   -- catatan internal tidak tampil ke pelapor
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (aduan_id) REFERENCES aduan(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;




